{"command":"set -euo pipefail
REPO='edburns/dd-3068633-darwin-arm64-05'; PR=4; EXPECTED_BASE='experiment/shepherd-control'
[ "$EXPECTED_BASE" != main ] || { echo 'ERROR: BASE_BRANCH must never be main'; exit 1; }
PR_JSON=$(gh pr view "$PR" -R "$REPO" --json state,isDraft,headRefOid,baseRefName,mergeable,mergeStateStatus,statusCheckRollup)
HEAD=$(printf '%s' "$PR_JSON" | jq -r '.headRefOid')
BASE=$(printf '%s' "$PR_JSON" | jq -r '.baseRefName')
[ "$BASE" = "$EXPECTED_BASE" ] || { gh pr edit "$PR" -R "$REPO" --base "$EXPECTED_BASE"; BASE=$(gh pr view "$PR" -R "$REPO" --json baseRefName --jq '.baseRefName'); [ "$BASE" = "$EXPECTED_BASE" ]; }
REVIEW=$(gh api "/repos/$REPO/pulls/$PR/reviews" | jq --arg head "$HEAD" '[.[] | select((.user.login // "") | test("^copilot-pull-request-reviewer(\\[bot\\])?$"; "i")) | select(.commit_id == $head)] | last // empty')
[ -n "$REVIEW" ] || { echo "NO_CURRENT_HEAD_COPILOT_REVIEW head=$HEAD"; exit 1; }
REFUSAL=$(printf '%s' "$REVIEW" | jq 'select((.body // "") | test("was" + "n\\u0027t able to review"; "i")) | select((.body // "") | test("maximum number of files"; "i"))')
[ -z "$REFUSAL" ] || { echo 'TOO_MANY_FILES_REFUSAL'; exit 1; }
OWNER=${REPO%%/*}; NAME=${REPO#*/}
THREADS=$(gh api graphql -F owner="$OWNER" -F name="$NAME" -F number="$PR" -f query='query($owner:String!,$name:String!,$number:Int!){repository(owner:$owner,name:$name){pullRequest(number:$number){reviewThreads(first:100){nodes{id isResolved comments(first:100){nodes{databaseId author{login} body}}}}}}}')
UNRESOLVED=$(printf '%s' "$THREADS" | jq '[.data.repository.pullRequest.reviewThreads.nodes[] | select(.isResolved == false)] | length')
[ "$UNRESOLVED" -eq 0 ] || { echo "UNRESOLVED_THREADS=$UNRESOLVED"; exit 1; }
BAD_CHECKS=$(printf '%s' "$PR_JSON" | jq '[.statusCheckRollup[] | select((.__typename == "CheckRun" and (.conclusion // "") != "SUCCESS" and (.name != "Block remove-before-merge paths") and (.name != "No remove-before-merge directories")) or (.__typename == "StatusContext" and .state != "SUCCESS"))] | length')
[ "$BAD_CHECKS" -eq 0 ] || { echo "BAD_CHECKS=$BAD_CHECKS"; printf '%s\n' "$PR_JSON" | jq '.statusCheckRollup'; exit 1; }
MERGEABLE=$(printf '%s' "$PR_JSON" | jq -r '.mergeable')
[ "$MERGEABLE" != CONFLICTING ] || { echo 'MERGE_CONFLICTS'; exit 1; }
echo "FINAL_GATES_OK head=$HEAD review_id=$(printf '%s' "$REVIEW" | jq -r '.id') base=$BASE mergeable=$MERGEABLE unresolved=$UNRESOLVED bad_checks=$BAD_CHECKS"
